{
  "items": [
    {
      "title": "Based on ISSP 2018: A Cross-national and Comparative Study of Religion of Additional 14 Countries",
      "url_or_doi": "https://doi.org/10.4232/1.13517",
      "justification": "Exact match for the requested dataset. Published in 2020 by the GESIS Data Archive, Cologne, under study identifier ZA7630, Version 1.0.0. The dataset contains survey data from the ISSP 2018 Religion IV module collected in 14 additional Asian and African countries: Algeria, Cambodia, Ghana, Indonesia, Jordan, Kenya, Malawi, Malaysia, Mongolia, Nepal, Nigeria, Singapore, Sri Lanka, and Vietnam. It examines religious beliefs, practices, attitudes, and social values. This DOI is the official persistent identifier for the dataset."
    },
    {
      "title": "Based on ISSP 2018: A Cross-national and Comparative Study of Religion of Additional 14 Countries — GESIS Data Catalogue",
      "url_or_doi": "https://search.gesis.org/research_data/ZA7630?lang=en",
      "justification": "Official dataset landing page hosted by GESIS, the repository responsible for archiving and distributing the study. Provides access to dataset metadata, documentation, and downloadable research data in formats such as SPSS and Stata. Registration is required for downloading the data. The study identifier ZA7630 confirms that this is the exact dataset requested."
    },
    {
      "title": "Based on ISSP 2018: A Cross-national and Comparative Study of Religion of Additional 14 Countries — ISSP Project Documentation",
      "url_or_doi": "https://www.gesis.org/en/issp/data-and-documentation/religion/2018/2018-additional-14-countries",
      "justification": "Official International Social Survey Programme documentation page hosted by GESIS. Describes the study's objectives, participating countries, sample sizes, fieldwork periods, questionnaires, and background variables. Also provides information about combining this dataset (ZA7630) with the international ISSP 2018 Religion IV dataset (ZA7570). The project was funded by the Templeton Religion Trust and coordinated by NORC."
    },
    {
      "title": "Based on ISSP 2018: A Cross-national and Comparative Study of Religion of Additional 14 Countries — B2FIND Dataset Record",
      "url_or_doi": "https://b2find.eudat.eu/dataset/e27194f9-a042-5fca-a1cd-e27ef47d8426",
      "justification": "Independent dataset discovery record indexed by B2FIND through the European research data infrastructure. Confirms the exact dataset title, DOI 10.4232/1.13517, publication year 2020, publisher GESIS Data Archive, and geographic coverage of 14 countries. Includes detailed information about survey topics, methodology, and access conditions."
    }
  ]
}
